function processField(html) {
  const withMarkers = String(html || '').replace(
    /<a\b[^>]*data-type=["']attachment["'][^>]*>[\s\S]*?<\/a>/gi,
    (anchor) => {
      const hrefMatch = anchor.match(/href=["']([^"']+)["']/i);

      if (!hrefMatch) {
        return anchor;
      }

      const href = hrefMatch[1].replace(/&amp;/gi, '&');
      const idMatch = href.match(/[?&]id=([^&]+)/i);

      if (!idMatch) {
        return anchor;
      }

      return `[[ATTACHMENT:id=${idMatch[1].trim()}]]`;
    }
  );

  return withMarkers.replace(/<img[^>]*>/gi, '');
}

const Incident = $('When Ivanti Incident Created').all();

return Incident.map(item => ({
  json: {
    ...item.json,
    Description: processField(item.json.Symptom)
  }
}));

function extractMarkerIds(text) {
  const ids = [];
  const re = /\[\[ATTACHMENT:id=([^\]]+)\]\]/gi;
  let match;

  while ((match = re.exec(String(text ?? ''))) !== null) {
    const id = match[1].trim();

    if (!ids.includes(id)) {
      ids.push(id);
    }
  }

  return ids;
}

function handleIncident(item) {
  let Attachments = $('Fetch Incident Related Attachments')
    .all()
    .filter(
      attachment =>
        attachment.json.ParentLink_RecID === item.json.RecId
    )
    .map(attachment => attachment.json.RecId);

  Attachments.push(
    ...extractMarkerIds(item.json.Description)
  );

  return {
    json: {
      ...item.json,
      Attachments
    }
  };
}

const Incidents = $('Tag Attachment Markers in Symptom').all();

return Incidents.map(item => handleIncident(item));

const Incidents = $('Extract Attachment RecIds from Tags').all();

let Attachments = [];

if ($('Fetch Attachment File Content').isExecuted) {
  Attachments = $('Fetch Attachment File Content').all();
}

function handleIncident(item) {
  const incident = item.json;
  const Description = $('Extract Symptom Text from HTML').all()[Incidents.indexOf(item)].json.Description;

  const matchingAttachments = Attachments.filter(attachment =>
    incident.Attachments.includes(attachment.json.Attachments)
  );

  const binary = {};

  matchingAttachments.forEach((attachment, index) => {
    if (attachment.binary?.data) {
      binary[`attachment_${index}`] = attachment.binary.data;
    }
  });

  return {
    json: {
      RecId: incident.RecId,
      Summary: incident.Subject,
      Status: incident.Status,
      Description: Description,
      TransactionId: incident.TransactionId
    },
    binary
  };
}

return Incidents.map(handleIncident);
